function render() {
  // 所有 UI 都從 state 取得資料
  document.getElementById('title').textContent = state.userName;
  document.getElementById('list').textContent = state.userName;
  document.getElementById('stats').textContent = state.userName;
}

// 更新資料後，重新渲染畫面
